      AND json_extract(p.body,'$.advanceRefund.paymentHash')=original.hash AND json_extract(p.body,'$.advanceRefund.paymentJournalId')=a.journal_id

      AND CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)>0 AND CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)<=(CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.net'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
      AND CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER) BETWEEN 0 AND (CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.tax'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
      AND CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER)=CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)+CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER) AND CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER)<=(CAST(replace(json_extract(original.body,'$.advancePayment.gross'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.gross'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
      AND CAST(replace(json_extract(p.body,'$.advanceRefund.controlAmount'),'.','') AS INTEGER)=CASE WHEN paid.amount_bani<0 THEN CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER) ELSE CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER) END
      AND json_extract(p.body,'$.advanceRefund.direction')=json_extract(original.body,'$.advancePayment.direction')
