      AND ((json_type(p.body,'$.advanceRefund.refundBasis') IS NULL AND (SELECT count(*) FROM acc_advance_refunds rf WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id)=0
        AND CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)=CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER) AND CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER)=CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER) AND CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER)=CAST(replace(json_extract(original.body,'$.advancePayment.gross'),'.','') AS INTEGER))
