          AND json_extract(p.body,'$.advanceRefund.refundBasis.priorRefundFinancialYearId') IS (SELECT json_extract(rp.body,'$.financialYearId') FROM acc_advance_refunds rf JOIN acc_journals rj ON rj.company_id=rf.company_id AND rj.id=rf.journal_id JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id ORDER BY rj.number DESC LIMIT 1)
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.before.net'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.net'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.after.net'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.net'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))-CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.before.tax'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.tax'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.after.tax'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.tax'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))-CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER)
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.before.gross'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.gross'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.gross'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.after.gross'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.gross'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.gross'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))-CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER)
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.before.controlAmount'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.controlAmount'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.controlAmount'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))
          AND CAST(replace(json_extract(p.body,'$.advanceRefund.refundBasis.after.controlAmount'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.controlAmount'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.controlAmount'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0))-CAST(replace(json_extract(p.body,'$.advanceRefund.controlAmount'),'.','') AS INTEGER)
          AND ((json_type(p.body,'$.advanceRefund.refundBasis.requestedNet')='null'
            AND CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.net'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0)) AND CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.tax'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0)))
            OR (json_type(p.body,'$.advanceRefund.refundBasis.requestedNet')='text'
              AND json_extract(p.body,'$.advanceRefund.refundBasis.requestedNet')=json_extract(p.body,'$.advanceRefund.net')
              AND (CASE json_extract(original.body,'$.advancePayment.ruleId') WHEN 'ro-domestic-standard-2025-01' THEN 19 WHEN 'ro-domestic-standard-2025-08' THEN 21 WHEN 'ro-domestic-non-vat-2025-2026' THEN 0 ELSE -1 END)>=0
              AND CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER)=CASE WHEN CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)=(CAST(replace(json_extract(original.body,'$.advancePayment.net'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.net'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0)) THEN (CAST(replace(json_extract(original.body,'$.advancePayment.tax'),'.','') AS INTEGER)-coalesce((SELECT sum(CAST(replace(json_extract(rp.body,'$.advanceRefund.tax'),'.','') AS INTEGER)) FROM acc_advance_refunds rf JOIN acc_proposals rp ON rp.company_id=rf.company_id AND rp.id=rf.proposal_id WHERE rf.company_id=a.company_id AND rf.payment_id=a.payment_id),0)) ELSE ((CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)/100)*(CASE json_extract(original.body,'$.advancePayment.ruleId') WHEN 'ro-domestic-standard-2025-01' THEN 19 WHEN 'ro-domestic-standard-2025-08' THEN 21 WHEN 'ro-domestic-non-vat-2025-2026' THEN 0 ELSE -1 END)+((CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER)%100)*(CASE json_extract(original.body,'$.advancePayment.ruleId') WHEN 'ro-domestic-standard-2025-01' THEN 19 WHEN 'ro-domestic-standard-2025-08' THEN 21 WHEN 'ro-domestic-non-vat-2025-2026' THEN 0 ELSE -1 END)+50)/100) END))
          AND e.id<>json_extract(original.body,'$.advancePayment.sourceEvidenceId')
