      AND NOT EXISTS(SELECT 1 FROM json_each(NEW.lines_json) l WHERE json_extract(l.value,'$.account') NOT IN(t.ledger_account,json_extract(p.body,'$.advanceRefund.controlAccount'),CASE WHEN m.amount_bani<0 THEN '4427' ELSE t.ledger_account END))
      AND NEW.lines_json=(SELECT json_group_array(json_object('account',account,'debitBani',CAST(debit AS TEXT),'creditBani',CAST(credit AS TEXT))) FROM (
        SELECT 1 ordinal,CASE WHEN paid.amount_bani<0 THEN t.ledger_account ELSE '419' END account,CASE WHEN paid.amount_bani<0 THEN CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER) ELSE CAST(replace(json_extract(p.body,'$.advanceRefund.net'),'.','') AS INTEGER) END debit,0 credit
        UNION ALL SELECT 2,CASE WHEN paid.amount_bani<0 THEN '4092' ELSE '4427' END,CASE WHEN paid.amount_bani>0 THEN CAST(replace(json_extract(p.body,'$.advanceRefund.tax'),'.','') AS INTEGER) ELSE 0 END,CASE WHEN paid.amount_bani<0 THEN CAST(replace(json_extract(p.body,'$.advanceRefund.gross'),'.','') AS INTEGER) ELSE 0 END
